/* Heisei Retro — 90s Japanese tech catalog: warm beige plastic, red/blue, dense boxes */
.theme-heisei-retro {
  --bg: oklch(0.923 0.025 89.2);
  --surface: oklch(0.958 0.019 90.5);
  --surface-2: oklch(0.883 0.031 90.3);
  --fg: oklch(0.244 0.008 84.6);
  --fg-muted: oklch(0.511 0.021 89.5);
  --accent: oklch(0.553 0.226 28.0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.511 0.148 250.8);
  --line: oklch(0.244 0.008 84.6);
  --success: oklch(0.522 0.140 146.9);
  --warning: oklch(0.679 0.142 76.5);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.25rem;
  --radius-sm: 0.125rem;
  --radius-lg: 0.375rem;
  --radius-pill: 0.375rem;
  --shadow-1: 2px 2px 0 oklch(0.2 0.01 85 / 25%);
  --shadow-2: 3px 3px 0 oklch(0.2 0.01 85 / 30%);
  --shadow-3: 5px 5px 0 oklch(0.2 0.01 85 / 30%);
  --glow: 0 0 0 2px color-mix(in oklab, var(--accent-2) 50%, transparent);
  --border-width: 2px;
  --blur-amount: 0px;
  --font-display: "Zen Kaku Gothic New", sans-serif;
  --font-body: "Zen Kaku Gothic New", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-heisei-retro h1,
.theme-heisei-retro h2,
.theme-heisei-retro h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-heisei-retro { background-image: radial-gradient(oklch(0.2 0.01 85 / 8%) 1px, transparent 1px); background-size: 12px 12px; }
.theme-heisei-retro h1 { border-bottom: 4px solid var(--accent); display: inline-block; padding-bottom: 0.2rem; }
.theme-heisei-retro button { box-shadow: 2px 2px 0 oklch(0.2 0.01 85 / 40%); }
.theme-heisei-retro button:active { transform: translate(2px, 2px); box-shadow: none; }

/* depth */
.theme-heisei-retro thead th { background: var(--accent); color: var(--accent-fg); font-weight: 700; letter-spacing: 0.06em; border: 1px solid oklch(0.4 0.17 28); padding-block: 0.35rem; }
.theme-heisei-retro td { border: 1px solid oklch(0.244 0.008 84.6 / 30%); }
.theme-heisei-retro tbody tr:nth-child(even) td { background: var(--surface-2); }
.theme-heisei-retro tbody tr:hover td { background: color-mix(in oklab, var(--accent-2) 12%, var(--surface)); }
.theme-heisei-retro input, .theme-heisei-retro textarea, .theme-heisei-retro select { border: 2px solid var(--line); background: oklch(0.985 0.01 92); border-radius: var(--radius-sm); }
.theme-heisei-retro input:focus-visible, .theme-heisei-retro textarea:focus-visible, .theme-heisei-retro select:focus-visible { outline: none; border-color: var(--accent-2); box-shadow: 0 0 0 2px color-mix(in oklab, var(--accent-2) 45%, transparent); }
.theme-heisei-retro kbd { font-family: var(--font-mono); font-size: 0.85em; border: 1px solid var(--line); border-bottom-width: 3px; background: linear-gradient(180deg, oklch(0.97 0.015 90), oklch(0.9 0.025 90)); border-radius: 0.25rem; padding: 0.1em 0.45em; }
.theme-heisei-retro a { color: var(--accent-2); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 2px; }
.theme-heisei-retro a:hover { color: var(--accent); background: color-mix(in oklab, var(--warning) 25%, transparent); }
.theme-heisei-retro ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-heisei-retro ::-webkit-scrollbar { width: 12px; }
.theme-heisei-retro ::-webkit-scrollbar-track { background: var(--surface-2); border-left: 1px solid var(--line); }
.theme-heisei-retro ::-webkit-scrollbar-thumb { background: linear-gradient(90deg, oklch(0.9 0.02 90), oklch(0.78 0.03 90)); border: 1px solid var(--line); border-radius: 2px; }
.theme-heisei-retro .label-caps { background: var(--accent); color: var(--accent-fg); padding: 0.1em 0.5em; border-radius: 2px; font-weight: 700; }
.theme-heisei-retro .themed-border { border: 2px solid var(--line); border-radius: var(--radius); box-shadow: 3px 3px 0 oklch(0.2 0.01 85 / 25%); background-image: linear-gradient(180deg, oklch(1 0 0 / 55%), transparent 30%); }
.theme-heisei-retro h2 { border-left: 6px solid var(--accent-2); padding-left: 0.5rem; }
.theme-heisei-retro hr { border: none; border-top: 1px solid var(--line); border-bottom: 3px double oklch(0.244 0.008 84.6 / 40%); }

/* alt mode: denki-ya at night — charcoal shelf, red/blue signage still glowing */
.theme-heisei-retro.alt-mode {
  --bg: oklch(0.22 0.015 80);
  --surface: oklch(0.27 0.015 82);
  --surface-2: oklch(0.32 0.02 84);
  --fg: oklch(0.94 0.015 90);
  --fg-muted: oklch(0.72 0.02 88);
  --accent: oklch(0.62 0.22 28);
  --accent-2: oklch(0.66 0.14 250);
  --line: oklch(0.94 0.015 90 / 35%);
  --shadow-1: 2px 2px 0 oklch(0 0 0 / 50%);
  --shadow-2: 3px 3px 0 oklch(0 0 0 / 55%);
  --shadow-3: 5px 5px 0 oklch(0 0 0 / 55%);
  background-image: radial-gradient(oklch(0.94 0.015 90 / 6%) 1px, transparent 1px);
  background-size: 12px 12px;
}
.theme-heisei-retro.alt-mode input, .theme-heisei-retro.alt-mode textarea, .theme-heisei-retro.alt-mode select { background: oklch(0.3 0.015 82); color: var(--fg); }
.theme-heisei-retro.alt-mode kbd { background: linear-gradient(180deg, oklch(0.38 0.02 84), oklch(0.3 0.015 82)); color: var(--fg); }
.theme-heisei-retro.alt-mode tbody tr:hover td { background: color-mix(in oklab, var(--accent-2) 18%, var(--surface)); }
.theme-heisei-retro.alt-mode ::-webkit-scrollbar-thumb { background: linear-gradient(90deg, oklch(0.45 0.02 84), oklch(0.35 0.02 84)); }
.theme-heisei-retro.alt-mode ::-webkit-scrollbar-track { background: var(--bg); }
.theme-heisei-retro.alt-mode .themed-border { background-image: none; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
